    return -EINVAL;
  }

  arg->tb_clk_rate = freq;

  if (arg->clk_rate == arg->tb_clk_rate)
    div = 0;
  else
    div = arg->clk_rate / arg->tb_clk_rate - 1;

  pwm_writel_bits(div, PWM_TBCTL_CLKDIV_MASK, PWM_TBCTL_CLKDIV_SHIFT,
                  PWM_TBCTL(ch));

