static int hal_pwm_calculate_div(u32 ch, float tar_freq) {
  struct aic_pwm_arg *arg = &g_pwm_args[ch];
  int div = -1, i = 0;
  uint32_t min_error = 5e6;
  uint32_t tar_freq_int = (uint32_t)(tar_freq * 100);

  for (i = 0; i < PWM_TBCTL_CLKDIV_MAX; ++i) {
    u32 count_value = arg->clk_rate * 100 / ((i + 1) * tar_freq_int);
    if (count_value < PWM_TBPRD_MAX) {
      uint32_t current_freq = arg->clk_rate * 100 / ((i + 1) * count_value);
      uint32_t error = abs(current_freq - tar_freq_int);

      if (error < min_error) {
        min_error = error;
        div = i;
      }
    }
  }

  hal_log_debug("div:%d\n", div);

  if (div < 0) {
    hal_log_err("calculate div error,should adjust the PWM_CLK_RATE.\n");
    return -1;
  }

  pwm_writel_bits(div, PWM_TBCTL_CLKDIV_MASK, PWM_TBCTL_CLKDIV_SHIFT,
                  PWM_TBCTL(ch));

  arg->tb_clk_rate = arg->clk_rate / (div + 1);

  return 0;
}

