static void test_report_phase(const char *name, int result)
{
  g_result.total++;

  if (result == TEST_RESULT_PASS)
    {
      g_result.passed++;
      syslog(LOG_INFO, "[PASS] %s\n", name);
    }
  else
    {
      g_result.failed++;
      syslog(LOG_INFO, "[FAIL] %s\n", name);
    }
}

