*** Begin Patch
*** Update File: app/lvgl_app/app_main/lvgl_app_backlight.c
@@
-#if defined(CONFIG_PWM) && defined(CONFIG_ARCH_CHIP_D13X)
-#  include "hal_pwm.h"
-#  define LVGL_APP_BACKLIGHT_HAVE_AIC_PWM 1
-#endif
-
 #define LVGL_APP_BACKLIGHT_TAG "backlight"
-#define LVGL_APP_BACKLIGHT_NSEC_PER_SEC 1000000000ull

 static int g_backlight_fd = -1;
 static bool g_backlight_applied;
 static bool g_backlight_warned;
-static bool g_backlight_fast_warned;
 static int32_t g_backlight_percent = -1;
-#ifdef LVGL_APP_BACKLIGHT_HAVE_AIC_PWM
-static int g_backlight_pwm_id = -1;
-#endif
@@
   return min_percent + ((100 - min_percent) * percent + 50) / 100;
 }

-#ifdef LVGL_APP_BACKLIGHT_HAVE_AIC_PWM
-static int lvgl_app_backlight_get_pwm_id(void)
-{
-  const char *path = CONFIG_LVGL_APP_BACKLIGHT_PWM_PATH;
-  const char *suffix;
-  int id = 0;
-
-  if (g_backlight_pwm_id >= 0)
-    {
-      return g_backlight_pwm_id;
-    }
-
-  suffix = path + strlen(path);
-  while (suffix > path && suffix[-1] >= '0' && suffix[-1] <= '9')
-    {
-      suffix--;
-    }
-
-  if (*suffix == '\0')
-    {
-      return -EINVAL;
-    }
-
-  while (*suffix != '\0')
-    {
-      id = id * 10 + *suffix - '0';
-      suffix++;
-    }
-
-  if (id < 0 || id >= PWM_ID_MAX_NUM)
-    {
-      return -EINVAL;
-    }
-
-  g_backlight_pwm_id = id;
-  return id;
-}
-
-static int lvgl_app_backlight_set_started_duty(int32_t hw_percent)
-{
-  uint32_t period_ns;
-  uint32_t duty_ns;
-  int pwm_id;
-  int ret;
-
-  if (CONFIG_LVGL_APP_BACKLIGHT_PWM_FREQUENCY <= 0)
-    {
-      return -EINVAL;
-    }
-
-  pwm_id = lvgl_app_backlight_get_pwm_id();
-  if (pwm_id < 0)
-    {
-      return pwm_id;
-    }
-
-  period_ns = LVGL_APP_BACKLIGHT_NSEC_PER_SEC /
-              CONFIG_LVGL_APP_BACKLIGHT_PWM_FREQUENCY;
-  if (period_ns == 0)
-    {
-      return -EINVAL;
-    }
-
-  duty_ns = (uint32_t)(((uint64_t)period_ns * hw_percent + 50u) / 100u);
-  if (duty_ns == 0)
-    {
-      duty_ns = 1;
-    }
-
-  ret = hal_pwm_set((uint32_t)pwm_id, duty_ns, period_ns, PWM_SET_CMPA);
-  if (ret < 0 && !g_backlight_fast_warned)
-    {
-      syslog(LOG_WARNING, "%s: fast pwm duty failed ret=%d\n",
-             LVGL_APP_BACKLIGHT_TAG, ret);
-      g_backlight_fast_warned = true;
-    }
-
-  return ret;
-}
